const body = $input.first().json.body ?? $input.first().json;
const userId         = body.user_id;
const transcript     = body.transcript;
const isPricingAudit = body.is_pricing_audit === true;
if (!userId)     throw new Error('S3: missing user_id');
if (!transcript) throw new Error('S3: missing transcript');
return [{ json: {
  user_id:          userId,
  transcript,
  is_pricing_audit: isPricingAudit,
  session_id:       body.session_id ?? null,
  created_at:       new Date().toISOString()
} }];

const insertedRows = $input.first().json;
const session = Array.isArray(insertedRows) ? insertedRows[0] : insertedRows;
if (!session?.id) {
  throw new Error('S3: session INSERT did not return an id — cannot proceed');
}
return [{ json: {
  session_id:       session.id,
  user_id:          $('Parse Session Payload').first().json.user_id,
  transcript:       $('Parse Session Payload').first().json.transcript,
  is_pricing_audit: $('Parse Session Payload').first().json.is_pricing_audit
} }];

const profileRows = $('Fetch Profile (goal context)').first().json;
const profile     = Array.isArray(profileRows) ? profileRows[0] : profileRows;
const sessionData    = $('Extract Session ID').first().json;
const emailRows     = $('Fetch User Email').first().json;
const userEmail     = (Array.isArray(emailRows) ? emailRows[0] : emailRows)?.email ?? null;
const transcript     = $('Parse Session Payload').first().json.transcript;
const goal90Day      = profile?.goal_90_day  ?? 'Not specified';
const prevScore      = profile?.goal_progress ?? 0;
const goalStartDate  = profile?.goal_start_date ?? new Date().toISOString();
const daysElapsed    = Math.floor((Date.now() - new Date(goalStartDate).getTime()) / (1000 * 60 * 60 * 24));

const prevSessionWrapped = $('Fetch Previous Session').first().json;
const prevSessionBody    = prevSessionWrapped?.body;
const prevSessionRow     = Array.isArray(prevSessionBody) && prevSessionBody.length > 0 ? prevSessionBody[0] : null;
const prevActionCommitted = prevSessionRow?.action_committed ?? null;

const scoringSystemPrompt = `You evaluate a founder's coaching session transcript against a fixed checklist.\nReturn ONLY valid JSON. No preamble, no explanation, no markdown.\nIf you cannot evaluate, return: {"confirmed_completion": false, "new_commitment": false, "blocker_found": false, "deliverable_produced": false, "reason": "insufficient data"}`;
const scoringUserPrompt = `GOAL: ${goal90Day}\nDAYS ELAPSED: ${daysElapsed} of 90\nPREVIOUS SESSION'S COMMITTED ACTION: ${prevActionCommitted ?? 'None — this is the first session for this founder, there is no prior commitment to confirm.'}\nSESSION TRANSCRIPT:\n${transcript}\n\n---\n\nEvaluate this session against ONLY the following checklist. For each item, decide true or false strictly from the transcript — do not infer generously, and do not compute any points or totals yourself.\n\nCHECKLIST:\n- confirmed_completion: true ONLY if the founder explicitly confirms they completed the exact action described in PREVIOUS SESSION'S COMMITTED ACTION above (or a clear equivalent). If PREVIOUS SESSION'S COMMITTED ACTION is "None", this MUST always be false, with no exceptions.\n- new_commitment: true if the founder makes a new, specific, measurable commitment to a future action related to the goal (whether self-driven or following a recommendation Marcus gave in this session).\n- blocker_found: true if the session uncovers a previously unknown blocker that, once resolved, advances the goal.\n- deliverable_produced: true if the session produces a concrete deliverable (copy, template, pricing decision, etc.).\n- off_topic: true if the session was exploratory or off-topic relative to the 90-day goal (in which case all the above should be false).\n\nDo not compute scores, deltas, or totals — only judge each checklist item as true or false. Scoring math is handled separately, outside this response.\n\nReturn ONLY this JSON object and absolutely nothing else — no text before it, no text after it:\n{"confirmed_completion": <bool>, "new_commitment": <bool>, "blocker_found": <bool>, "deliverable_produced": <bool>, "reason": "<one sentence, max 20 words>"}`;

const summarySystemPrompt = `You are Marcus, a direct AI business coach. Summarise this coaching session in exactly 3 bullet points. Then identify the single most important action the founder committed to. Return ONLY valid JSON: {"summary": ["bullet1", "bullet2", "bullet3"], "action_committed": "string"}`;
const summaryUserPrompt = `SESSION TRANSCRIPT:\n${transcript}`;

return [{ json: {
  session_id:       sessionData.session_id,
  user_id:          sessionData.user_id,
  email:            userEmail,
  prev_score:       prevScore,
  goal_90_day:      goal90Day,
  is_pricing_audit: sessionData.is_pricing_audit,
  scoring_payload: {
    model: 'claude-sonnet-4-6',
    max_tokens: 256,
    system: scoringSystemPrompt,
    messages: [{ role: 'user', content: scoringUserPrompt }]
  },
  summary_payload: {
    model: 'claude-sonnet-4-6',
    max_tokens: 512,
    system: summarySystemPrompt,
    messages: [{ role: 'user', content: summaryUserPrompt }]
  }
} }];

const rawText = $input.first().json?.content?.[0]?.text?.trim() ?? '';
const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const jsonMatches = cleaned.match(/\{[^{}]*\}/g);
const raw = jsonMatches && jsonMatches.length > 0 ? jsonMatches[jsonMatches.length - 1] : cleaned;
const prevScore = $('Build Anthropic Requests').first().json.prev_score;

let flags;
try {
  flags = JSON.parse(raw);
} catch (e) {
  flags = { confirmed_completion: false, new_commitment: false, blocker_found: false, deliverable_produced: false, reason: 'Scoring parse error — score unchanged' };
}

let delta = 0;
if (flags.confirmed_completion === true) delta += 20;
if (flags.new_commitment === true)       delta += 5;
if (flags.blocker_found === true)        delta += 5;
if (flags.deliverable_produced === true) delta += 5;
delta = Math.min(25, delta);

const score = Math.min(100, prevScore + delta);
return [{ json: { score, delta, reason: flags.reason ?? '' } }];

const rawText = $input.first().json?.content?.[0]?.text?.trim() ?? '';
const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const jsonMatches = cleaned.match(/\{[^{}]*\}/g);
const raw = jsonMatches && jsonMatches.length > 0 ? jsonMatches[jsonMatches.length - 1] : cleaned;
let result;
try {
  result = JSON.parse(raw);
} catch (e) {
  result = { summary: ['Session complete.', 'Summary unavailable — will retry.', ''], action_committed: '' };
}
const summary = Array.isArray(result.summary)
  ? result.summary.filter(Boolean).join(' | ')
  : (result.summary ?? 'Summary unavailable');
return [{ json: { summary, action_committed: result.action_committed ?? '' } }];

const score   = $('Parse Scoring Response').first().json;
const summary = $('Parse Summary Response').first().json;
const req     = $('Build Anthropic Requests').first().json;
return [{ json: {
  session_id:       req.session_id,
  user_id:          req.user_id,
  email:            req.email,
  is_pricing_audit: req.is_pricing_audit,
  goal_90_day:      req.goal_90_day,
  new_score:        score.score,
  score_delta:      score.delta,
  score_reason:     score.reason,
  summary:          summary.summary,
  action_committed: summary.action_committed
} }];
